# iso_usb_msc_glue.c の、手書きのミュータント(C-16)。tools/test/gen_iso_mutants.py は、次の形を作らないので、ここで足す:
# 方向の対応表(map_bot_dir_to_mmc)の戻り値、mmc_scsi_execute / mmc_scsi_read_blocks / iso_extent_map / read_sectors / iso_extent_valid_bytes への引数、
# 結果の欄の値(`out_res->x = ...`)、行の先頭が `*` の文(`*handle = ...`、`*out = ...`。機械は、コメントの行と見なして作らない)、
# リゾルバの関数ポインターの取り違え、`ISO_ERR_*` の戻り値の取り違え、`set_image` の参照とロックの順序、ゼロ埋めの範囲、
# `iso_usb_msc_on_disconnect_media` が呼ぶ関数、`as_scsi` の欄。iso_msc_mutants.py(機械が作る)とは別に、同じスクリプトで実行する:
#   python3 tools/test/mutate_iso_msc.py <repo> <workdir> tools/test/iso_msc_mutants_extra.py <out_extra.json> -j3
GL = "components/iso_usb_msc/iso_usb_msc_glue.c"
INC = '#include "iso_usb_msc_glue.h"'
PRAGMAS = '\n#pragma GCC diagnostic ignored "-Wparentheses"\n#pragma GCC diagnostic ignored "-Wunused-but-set-variable"\n#pragma GCC diagnostic ignored "-Wunused-variable"\n#pragma GCC diagnostic ignored "-Wunused-parameter"\n#pragma GCC diagnostic ignored "-Wunused-function"\n#pragma GCC diagnostic ignored "-Wmaybe-uninitialized"\n#pragma GCC diagnostic ignored "-Wuninitialized"\n#pragma GCC diagnostic ignored "-Warray-parameter"\n#pragma GCC diagnostic ignored "-Wstringop-overflow"\n#pragma GCC diagnostic ignored "-Wtype-limits"\n#pragma GCC diagnostic ignored "-Wsign-compare"\n#pragma GCC diagnostic ignored "-Wreturn-type"'

EXEC = "mmc_scsi_execute(scsi, cmd->cdb, cmd->cdb_len, map_bot_dir_to_mmc(cmd->dir),\n                         cmd->expected_len, cmd->out, cmd->out_cap, &mr);"
RDB = "mmc_scsi_read_blocks(scsi, (uint32_t)cmd->lba, cmd->blocks, cmd->buf, cmd->cap);"
MAP = "iso_extent_map(tbl, (uint64_t)cur_lba, step, spans,\n                                          sizeof(spans) / sizeof(spans[0]), &n_spans);"
RS = "bdev->read_sectors(bdev->ctx, epoch, spans[i].start_sector,\n                                              spans[i].sector_count, dst);"
ZF = "memset(out_ptr + (size_t)valid, 0, step_bytes - (size_t)valid);"
DEV_R = "out_res->dev_dir = (mr.read.blocks > 0u) ? MSC_BOT_DIR_IN : MSC_BOT_DIR_NONE;"
DEV_D = "out_res->dev_dir = (mr.data_len > 0u) ? MSC_BOT_DIR_IN : MSC_BOT_DIR_NONE;"


def M(id, desc, old, new, file=GL):
    return {"id": id, "desc": desc, "edits": [(old, new), (INC, INC + PRAGMAS)], "file": file}


